class _BinaryConverter:
    def __init__(self):
        self._cache = {}
        self._base = 2
        self._max_cache_size = 100
        self._current_size = 0

    def _convert_single_digit(self, digit):
        if digit == 0:
            return '0'

        self._remainder_list = []
        _n = digit
        while _n > 0:
            self._remainder_list.append(str(_n % self._base))
            _n //= self._base
        return "".join(reversed(self._remainder_list))

    def _get_from_cache(self, decimal_int):
        return self._cache.get(decimal_int)

    def _add_to_cache(self, decimal_int, binary_string):
        if self._current_size < self._max_cache_size:
            self._cache[decimal_int] = binary_string
            self._current_size += 1

    def convert(self, decimal_int):
        if not isinstance(decimal_int, int) or decimal_int < 0:
            raise ValueError("Input must be a non-negative integer.")

        _cached_result = self._get_from_cache(decimal_int)
        if _cached_result is not None:
            return _cached_result

        _binary_representation = self._convert_single_digit(decimal_int)
        self._add_to_cache(decimal_int, _binary_representation)
