class _BinaryConverter:
    def __init__(self):
        self.__cache = {}
        self.__base = 2
        self.__max_cache_size = 100
        self.__current_size = 0

    def __convert_single_digit(self, digit):
        if digit == 0:
            return '0'

        self.__remainder_list = []
        _n = digit
        while _n > 0:
            self.__remainder_list.append(str(_n % self.__base))
            _n //= self.__base
        return "".join(reversed(self.__remainder_list))

    def __get_from_cache(self, decimal_int):
        return self.__cache.get(decimal_int)

    def __add_to_cache(self, decimal_int, binary_string):
        if self.__current_size < self.__max_cache_size:
            self.__cache[decimal_int] = binary_string
            self.__current_size += 1

    def convert(self, decimal_int):
        if not isinstance(decimal_int, int) or decimal_int < 0:
            raise ValueError("Input must be a non-negative integer.")

        _cached_result = self.__get_from_cache(decimal_int)
        if _cached_result is not None:
            return _cached_result

        _binary_representation = self.__convert_single_digit(decimal_int)
        self.__add_to_cache(decimal_int, _binary_representation)
        return _binary_representation

