import math

class _StdDevCalculator:
    def __init__(self, _numbers):
        self._data = list(_numbers)
        self._n = len(self._data)
        self._mean = None
        self._variance = None
        self._std_dev = None
        self._is_calculated = False
        self._sum_of_squares = 0.0
        self._sum_of_numbers = 0.0

    def _calculate_mean(self):
        self._sum_of_numbers = sum(self._data)
        self._mean = self._sum_of_numbers / self._n

    def _calculate_variance(self):
        if self._mean is None:
            self._calculate_mean()
        self._sum_of_squares = sum((x - self._mean) ** 2 for x in self._data)
        self._variance = self._sum_of_squares / (self._n - 1)

    def _calculate_std_dev_internal(self):
        if self._variance is None:
            self._calculate_variance()
        self._std_dev = math.sqrt(self._variance)
        self._is_calculated = True

    def get_std_dev(self):
        if not self._is_calculated:
            self._calculate_std_dev_internal()
        return self._std_dev

def calculate_std_dev(numbers):
    _calculator = _StdDevCalculator(numbers)
    return _calculator.get_std_dev()

