        self._last_outcomes = []
        self._max_possible_sides = 100
        self._min_possible_sides = 2
        self._random_generator = random.Random()
        if _seed is not None:
            self._random_generator.seed(_seed)
        self._history_size = 10
        self._roll_history = []

    def _validate_input(self, _num_dice, _sides):
        if not isinstance(_num_dice, int) or _num_dice <= 0:
            raise ValueError("Number of dice must be a positive integer.")
        if not isinstance(_sides, int) or not (self._min_possible_sides <= _sides <= self._max_possible_sides):
            raise ValueError(f"Number of sides must be an integer between {self._min_possible_sides} and {self._max_possible_sides}.")

    def _generate_single_roll(self, _sides):
        return self._random_generator.randint(1, _sides)

    def _update_history(self, _num_dice, _sides, _outcomes):
        self._roll_history.append({'num_dice': _num_dice, 'sides': _sides, 'outcomes': _outcomes})
        if len(self._roll_history) > self._history_size:
            self._roll_history.pop(0)

    def roll_dice(self, num_dice, sides):
        self._validate_input(num_dice, sides)
        _results = []
        for _i in range(num_dice):
