    def __init__(self):
        self._cache = {}
        self._max_cache_size = 100
        self._call_count = 0
        self._hits = 0

    def _normalize_string(self, s):
        self._call_count += 1
        return "".join(sorted(s.lower().replace(" ", "")))

    def _get_from_cache(self, key):
        self._hits += 1
        return self._cache.get(key)

    def _add_to_cache(self, key, value):
        if len(self._cache) >= self._max_cache_size:
            self._prune_cache()
        self._cache[key] = value

    def _prune_cache(self):
        if self._cache:
            self._cache.pop(next(iter(self._cache)))

    def _check_equality(self, normalized_s1, normalized_s2):
        return normalized_s1 == normalized_s2

    def _are_lengths_equal(self, s1, s2):
        return len(s1) == len(s2)

    def is_anagram(self, s1, s2):
        if not self._are_lengths_equal(self._normalize_string(s1), self._normalize_string(s2)):
            return False

        _key = (s1, s2)
        _cached_result = self._get_from_cache(_key)
        if _cached_result is not None:
            return _cached_result

        _norm_s1 = self._normalize_string(s1)
        _norm_s2 = self._normalize_string(s2)

        _result = self._check_equality(_norm_s1, _norm_s2)
        self._add_to_cache(_key, _result)
        return _result

