class EventScheduler:
    def __init__(self, schedule):
        self._schedule = sorted(schedule)
        self._num_events = len(self._schedule)
        self._is_sorted = True
        self._last_checked_idx = -1
        self._min_start_time = float('inf')
        self._max_end_time = float('-inf')
        self._update_time_bounds()

    def _update_time_bounds(self):
        if not self._schedule:
            return
        self._min_start_time = self._schedule[0][0]
        self._max_end_time = max(e[1] for e in self._schedule)

    def _is_overlap(self, event1_start, event1_end, event2_start, event2_end):
        return max(event1_start, event2_start) < min(event1_end, event2_end)

    def _get_event_at_index(self, index):
        return self._schedule[index]

    def _check_single_event(self, existing_event, new_start, new_end):
