    def __init__(self, schedule):
        self.__schedule = sorted(schedule)
        self.__num_events = len(self.__schedule)
        self.__is_sorted = True
        self.__last_checked_idx = -1
        self.__min_start_time = float('inf')
        self.__max_end_time = float('-inf')
        self.__update_time_bounds()

    def __update_time_bounds(self):
        if not self.__schedule:
            return
        self.__min_start_time = self.__schedule[0][0]
        self.__max_end_time = max(e[1] for e in self.__schedule)

    def __is_overlap(self, event1_start, event1_end, event2_start, event2_end):
        return max(event1_start, event2_start) < min(event1_end, event2_end)

    def __get_event_at_index(self, index):
