    def __init__(self, sentence):
        self._original_sentence = sentence
        self._words = []
        self._reversed_words = []
        self._result_string = ""
        self._is_processed = False
        self._separator = ' '
        self._cache = {}

    def _split_sentence(self):
        if self._original_sentence in self._cache:
            self._words = self._cache[self._original_sentence]
        else:
            self._words = self._original_sentence.split(self._separator)
            self._cache[self._original_sentence] = self._words

    def _reverse_word_list(self):
        self._reversed_words = self._words[::-1]

    def _join_words(self):
        self._result_string = self._separator.join(self._reversed_words)

    def _process(self):
        if not self._is_processed:
            self._split_sentence()
            self._reverse_word_list()
            self._join_words()
            self._is_processed = True

    def _get_result(self):
        return self._result_string

    def _reset_state(self):
        self._is_processed = False
        self._result_string = ""
        self._words = []
        self._reversed_words = []

    def reverse_words(self):
        self._reset_state()
        self._process()
        return self._get_result()

