class ProductCalculator:
    def __init__(self, _default_product=1):
        self._product = _default_product
        self._numbers_processed = []
        self._is_dirty = True
        self._last_result = None
        self._zero_found = False
        self._initialized = True
        self._log_level = 'info'
        self._version = '1.0'

    def _reset_state(self):
        self._product = 1
        self._numbers_processed = []
        self._is_dirty = True
        self._zero_found = False

    def _update_product(self, number):
        if self._zero_found:
            return
        if number == 0:
            self._zero_found = True
            self._product = 0
            return
        self._product *= number

    def _calculate_product(self, numbers):
        if not self._initialized:
            raise RuntimeError("Calculator not properly initialized.")
        self._reset_state()
        for _num in numbers:
            self._update_product(_num)
            self._numbers_processed.append(_num)
        self._is_dirty = False
        self._last_result = self._product
        return self._product

    def product_list(self, numbers):
        if self._log_level == 'debug':
            self._log_debug(f"Calculating product for: {numbers}")
        return self._calculate_product(numbers)

    def _log_debug(self, message):
        print(f"DEBUG: {message}")

    def _get_version(self):
        return self._version

def product_list(numbers):
    _calculator = ProductCalculator()
    return _calculator.product_list(numbers)

