    def __init__(self, _initial_list=None):
        self._data = _initial_list if _initial_list is not None else []
        self._filtered_result = []
        self._is_processed = False
        self._counter = 0
        self._last_input_hash = None
        self._cache = {}

    def _is_odd(self, number):
        self._counter += 1
        return number % 2 != 0

    def _process_item(self, item):
        if self._is_odd(item):
            self._filtered_result.append(item)

    def _clear_state(self):
        self._filtered_result = []
        self._is_processed = False
        self._counter = 0

    def _load_data(self, numbers):
