        self._clear_state()

    def _get_hash(self, numbers):
        return hash(tuple(numbers))

    def filter_odd(self, numbers):
        current_hash = self._get_hash(numbers)
        if current_hash == self._last_input_hash and self._is_processed and current_hash in self._cache:
            return self._cache[current_hash]

        self._load_data(numbers)
        for _num in self._data:
            self._process_item(_num)
        self._is_processed = True
        self._last_input_hash = current_hash
        self._cache[current_hash] = self._filtered_result[:]
        return self._filtered_result[:]

def filter_odd(numbers):
