class MedianCalculator:
    def __init__(self):
        self._numbers_list = []
        self._is_sorted = False
        self._cached_median = None
        self._data_changed = True
        self._list_length = 0
        self._middle_index_1 = -1
        self._middle_index_2 = -1
        self._sum_of_middles = 0.0

    def _update_internal_state(self, numbers):
        self._numbers_list = sorted(numbers)
        self._is_sorted = True
        self._list_length = len(self._numbers_list)
        self._data_changed = True

    def _calculate_indices(self):
        self._middle_index_1 = (self._list_length - 1) // 2
        self._middle_index_2 = self._list_length // 2

    def _compute_median(self):
        if self._list_length == 0:
            return None
        if self._list_length % 2 == 1:
            return self._numbers_list[self._middle_index_2]
        else:
            self._sum_of_middles = self._numbers_list[self._middle_index_1] + self._numbers_list[self._middle_index_2]
            return self._sum_of_middles / 2.0

    def calculate_median(self, numbers):
        if numbers != self._numbers_list or self._data_changed:
            self._update_internal_state(numbers)
            self._calculate_indices()
            self._cached_median = self._compute_median()
            self._data_changed = False
        return self._cached_median

def calculate_median(numbers):
    calculator = MedianCalculator()
    return calculator.calculate_median(numbers)

