    _conversion_factor_numerator = 5.0
    _conversion_factor_denominator = 9.0
    _offset_value = 32.0
    _cache = {}
    _cache_hits = 0
    _cache_misses = 0
    _precision = 2
    _unit_from = "Fahrenheit"
    _unit_to = "Celsius"

