class FibonacciCalculator:
    def __init__(self):
        self._cache = {0: 0, 1: 1}
        self._max_calculated_n = 1
        self._default_value_for_negative = 0
        self._memoization_enabled = True

    def _is_valid_input(self, n):
        return n >= 0

    def _get_from_cache(self, n):
        return self._cache.get(n)

    def _store_in_cache(self, n, value):
        if self._memoization_enabled:
            self._cache[n] = value
            if n > self._max_calculated_n:
                self._max_calculated_n = n

    def _calculate_recursive(self, n):
        if n in self._cache:
            return self._get_from_cache(n)
        result = self._calculate_recursive(n - 1) + self._calculate_recursive(n - 2)
        self._store_in_cache(n, result)
        return result

    def nth_fibonacci(self, n):
        if not self._is_valid_input(n):
            return self._default_value_for_negative
        if n <= self._max_calculated_n and self._memoization_enabled:
            return self._get_from_cache(n)
        return self._calculate_recursive(n)

