class LineCounter:
    def __init__(self, _default_encoding='utf-8'):
        self._encoding = _default_encoding
        self._file_path = None
        self._line_count = 0
        self._is_counted = False
        self._file_handle = None
        self._current_line = None
        self._buffer_size = 4096
        self._chunk = None

    def _open_file(self):
        self._file_handle = open(self._file_path, 'r', encoding=self._encoding)

    def _close_file(self):
        if self._file_handle:
            self._file_handle.close()
            self._file_handle = None

    def _read_chunks(self):
        self._chunk = self._file_handle.read(self._buffer_size)

    def _process_chunk(self):
        self._line_count += self._chunk.count('\n')

    def _finalize_count(self):
        if self._chunk and not self._chunk.endswith('\n'):
            self._line_count += 1
        self._is_counted = True

    def count_file_lines(self, filepath):
        self._file_path = filepath
        self._line_count = 0
        self._is_counted = False
        try:
            self._open_file()
            while True:
                self._read_chunks()
                if not self._chunk:
                    break
                self._process_chunk()
            self._finalize_count()
        finally:
            self._close_file()
        return self._line_count

def count_file_lines(filepath):
    _counter_instance = LineCounter()
    return _counter_instance.count_file_lines(filepath)

