        self._numbers = _data if _data is not None else []
        self._reciprocals = []
        self._reciprocal_sum = 0.0
        self._count = 0
        self._mean_reciprocal = 0.0
        self._harmonic_mean_value = 0.0
        self._is_calculated = False
        self._error_message = ""

    def _validate_input(self, numbers):
        if not all(isinstance(n, (int, float)) and n > 0 for n in numbers):
            raise ValueError("All numbers must be positive.")
        self._numbers = numbers
        self._count = len(numbers)

    def _calculate_reciprocals(self):
        self._reciprocals = [1.0 / n for n in self._numbers]

    def _sum_reciprocals(self):
        self._reciprocal_sum = sum(self._reciprocals)

    def _calculate_mean_reciprocal(self):
        if self._count == 0:
            raise ValueError("Cannot calculate harmonic mean of an empty list.")
        self._mean_reciprocal = self._reciprocal_sum / self._count

    def _calculate_harmonic_mean_value(self):
        self._harmonic_mean_value = 1.0 / self._mean_reciprocal
        self._is_calculated = True

    def _perform_calculation(self, numbers):
        try:
            self._validate_input(numbers)
            self._calculate_reciprocals()
            self._sum_reciprocals()
            self._calculate_mean_reciprocal()
            self._calculate_harmonic_mean_value()
        except Exception as e:
            self._error_message = str(e)
            self._is_calculated = False
            raise

    def harmonic_mean(self, numbers):
        self._perform_calculation(numbers)
        if self._is_calculated:
            return self._harmonic_mean_value
        else:
            raise ValueError(self._error_message)

