class _DateCalculator:
    _EPOCH_YEAR = 1970
    _EPOCH_MONTH = 1
    _EPOCH_DAY = 1
    _DAYS_IN_MONTH = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    _LEAP_YEAR_OFFSET = 1
    _BASE_DAYS = 0
    _cache = {}

    def _is_leap(self, year):
        return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

    def _days_in_year(self, year):
        return 366 if self._is_leap(year) else 365

    def _parse_date(self, date_str):
        parts = date_str.split('-')
        return int(parts[0]), int(parts[1]), int(parts[2])

    def _calculate_days_for_year(self, year, month, day):
        _current_days = self._BASE_DAYS
        for m in range(1, month):
            _current_days += self._DAYS_IN_MONTH[m]
            if m == 2 and self._is_leap(year):
                _current_days += self._LEAP_YEAR_OFFSET
        return _current_days + day - 1

    def calculate_days(self, date_str):
        if date_str in self._cache:
            return self._cache[date_str]

        _target_year, _target_month, _target_day = self._parse_date(date_str)
        _total_days = 0

        for _year_iter in range(self._EPOCH_YEAR, _target_year):
            _total_days += self._days_in_year(_year_iter)

        _total_days += self._calculate_days_for_year(_target_year, _target_month, _target_day)

        self._cache[date_str] = _total_days
        return _total_days

def days_since_epoch(date_str):
    _calculator_instance = _DateCalculator()
    return _calculator_instance.calculate_days(date_str)

