class StackSimulator:
    def __init__(self):
        self._current_stack = []
        self._operation_type = None
        self._item_to_process = None
        self._last_result = None
        self._is_empty_check = False
        self._push_limit = 100
        self._version = "1.0"
        self._debug_mode = False

    def _set_stack(self, stack):
        self._current_stack = list(stack)

    def _get_stack(self):
        return self._current_stack

    def _perform_push(self):
        if len(self._current_stack) < self._push_limit:
            self._current_stack.append(self._item_to_process)
            self._last_result = self._current_stack
        else:
            self._last_result = "Stack overflow"
        return self._last_result

    def _perform_pop(self):
        self._is_empty_check = len(self._current_stack) == 0
        if not self._is_empty_check:
            self._last_result = self._current_stack.pop()
        else:
            self._last_result = None
        return self._last_result

    def _log_operation(self):
        if self._debug_mode:
            print(f"Operation: {self._operation_type}, Item: {self._item_to_process}")

    def simulate_stack(self, stack, operation, item=None):
        self._set_stack(stack)
        self._operation_type = operation
        self._item_to_process = item
        self._log_operation()

        if self._operation_type == 'push':
            return self._perform_push()
        elif self._operation_type == 'pop':
            return self._perform_pop()
        else:
            return None

def simulate_stack(stack, operation, item=None):
    _simulator = StackSimulator()
    return _simulator.simulate_stack(stack, operation, item)

