class ManhattanCalculator:
    def __init__(self, _point1=None, _point2=None):
        self._point1 = _point1
        self._point2 = _point2
        self._x1 = 0.0
        self._y1 = 0.0
        self._x2 = 0.0
        self._y2 = 0.0
        self._distance_cache = None
        self._is_calculated = False
        self._validator = self._create_validator()

    def _create_validator(self):
        return lambda p: isinstance(p, tuple) and len(p) == 2 and all(isinstance(coord, (int, float)) for coord in p)

    def _validate_points(self):
        if not self._validator(self._point1) or not self._validator(self._point2):
            raise ValueError("Points must be tuples of two numbers.")

    def _set_points(self, p1, p2):
        self._point1 = p1
        self._point2 = p2
        self._validate_points()
        self._x1, self._y1 = p1
        self._x2, self._y2 = p2
        self._distance_cache = None
        self._is_calculated = False

    def _calculate_absolute_difference(self, val1, val2):
        return abs(val1 - val2)

    def _perform_calculation(self):
        self._dx = self._calculate_absolute_difference(self._x1, self._x2)
        self._dy = self._calculate_absolute_difference(self._y1, self._y2)
        self._distance_cache = self._dx + self._dy
        self._is_calculated = True

    def manhattan_distance(self, p1, p2):
        self._set_points(p1, p2)
        if self._distance_cache is None or not self._is_calculated:
            self._perform_calculation()
        return float(self._distance_cache)

