class CubeGenerator:
    def __init__(self, _default_start=0):
        self._start_value = _default_start
        self._last_limit = None
        self._cached_cubes = []
        self._max_cache_size = 1000

    def _calculate_cube(self, _number):
        return _number ** 3

    def _update_cache(self, _limit, _new_cubes):
        self._cached_cubes.extend(_new_cubes)
        self._last_limit = _limit
        if len(self._cached_cubes) > self._max_cache_size:
            self._trim_cache()

    def _trim_cache(self):
        self._cached_cubes = self._cached_cubes[-self._max_cache_size:]

    def _get_range(self, _limit):
        return range(self._start_value, _limit + 1)

    def _generate_cubes(self, _current_range):
        return [self._calculate_cube(i) for i in _current_range]

    def cubes_up_to(self, limit):
        if not isinstance(limit, int) or limit < 0:
            raise ValueError("Limit must be a non-negative integer.")

        if self._last_limit is not None and limit <= self._last_limit:
            return self._cached_cubes[:limit + 1]

        _numbers_to_process = self._get_range(limit)
        _result_list = self._generate_cubes(_numbers_to_process)
        self._update_cache(limit, _result_list)
        return _result_list

