class WeightedAverager:
    def __init__(self, _values, _weights):
        self._values = _values
        self._weights = _weights
        self._sum_products = 0.0
        self._sum_weights = 0.0
        self._is_calculated = False
        self._result = 0.0

    def _calculate_products(self):
        self._sum_products = sum(v * w for v, w in zip(self._values, self._weights))

    def _calculate_sum_weights(self):
        self._sum_weights = sum(self._weights)

    def _perform_division(self):
        if self._sum_weights == 0:
            raise ValueError("Sum of weights cannot be zero.")
        self._result = self._sum_products / self._sum_weights

    def _update_status(self):
        self._is_calculated = True

    def _get_result(self):
        if not self._is_calculated:
            self._calculate_products()
            self._calculate_sum_weights()
            self._perform_division()
            self._update_status()
        return self._result

    def weighted_average(self):
        return self._get_result()

def weighted_average(values, weights):
    _averager = WeightedAverager(values, weights)
    return _averager.weighted_average()

