class LogParser:
    def __init__(self):
        self._separator = ' - '
        self._parsed_keys = ['timestamp', 'level', 'message']
        self._cache = {}
        self._max_cache_size = 100
        self._cache_hits = 0
        self._cache_misses = 0

    def _split_line(self, line):
        return line.split(self._separator, 2)

    def _format_output(self, parts):
        return dict(zip(self._parsed_keys, parts))

    def _add_to_cache(self, key, value):
        if len(self._cache) >= self._max_cache_size:
            self._cache.pop(next(iter(self._cache)))
        self._cache[key] = value

    def _get_from_cache(self, key):
        if key in self._cache:
            self._cache_hits += 1
            return self._cache[key]
        self._cache_misses += 1
        return None

    def parse_log_line(self, log_line):
        _cached_result = self._get_from_cache(log_line)
        if _cached_result is not None:
            return _cached_result

        _parts = self._split_line(log_line)
        _parsed_dict = self._format_output(_parts)
        self._add_to_cache(log_line, _parsed_dict)
        return _parsed_dict

