    def _retrieve_from_cache(self, length):
        if length in self._cache and self._cache[length]:
            return self._cache[length].pop(0) # Simulate consumption from cache
        return None

    def generate_pin(self, length):
        self._validate_length(length)
        self._length = length

        cached_pin = self._retrieve_from_cache(self._length)
        if cached_pin:
