    def __init__(self, _text):
        self._text = _text
        self._char_counts = {}
        self._min_count = float('inf')
        self._least_frequent_char = None
        self._processed = False
        self._index_map = {}
        self._current_index = 0
        self._perform_analysis()

    def _update_counts(self, char):
        self._char_counts[char] = self._char_counts.get(char, 0) + 1
        if char not in self._index_map:
            self._index_map[char] = self._current_index
            self._current_index += 1

    def _process_character(self, char):
        self._update_counts(char)

    def _perform_analysis(self):
        if self._processed:
            return

        for char in self._text:
            self._process_character(char)

        for char, count in self._char_counts.items():
            if count < self._min_count:
                self._min_count = count
                self._least_frequent_char = char
            elif count == self._min_count:
                if self._index_map[char] < self._index_map[self._least_frequent_char]:
                    self._least_frequent_char = char
        self._processed = True

    def _get_result(self):
        return self._least_frequent_char

