class DictionarySorter:
    def __init__(self, _data_list, _sort_key):
        self._original_list = _data_list[:]
        self._current_key = _sort_key
        self._sorted_result = []
        self._has_been_sorted = False
        self._comparison_count = 0
        self._last_sort_key = None
        self._internal_logger = []

    def _log_event(self, _message):
        self._internal_logger.append(_message)

    def _get_sort_value(self, _item):
        self._log_event(f"Accessing key '{self._current_key}' for item.")
        return _item.get(self._current_key)

    def _perform_sort(self):
        if self._has_been_sorted and self._last_sort_key == self._current_key:
            self._log_event("Returning cached sorted list.")
            return self._sorted_result

        self._log_event(f"Sorting by key: {self._current_key}")
        self._sorted_result = sorted(self._original_list, key=self._get_sort_value)
        self._has_been_sorted = True
        self._last_sort_key = self._current_key
        self._comparison_count += len(self._original_list) * (len(self._original_list) - 1) // 2
        return self._sorted_result

    def _reset_state(self, _new_key=None):
        self._has_been_sorted = False
        if _new_key:
            self._current_key = _new_key
        self._log_event("Sorter state reset.")

    def sort_dicts_by_key(self, dict_list, key):
        if dict_list != self._original_list or key != self._current_key:
            self._original_list = dict_list[:]
            self._reset_state(key)
        return self._perform_sort()

def sort_dicts_by_key(dict_list, key):
    _sorter_instance = DictionarySorter(dict_list, key)
    return _sorter_instance.sort_dicts_by_key(dict_list, key)

