class TimesTableGenerator:
    def __init__(self, _number, _limit):
        self._number = _number
        self._limit = _limit
        self._table_list = []
        self._current_multiplier = 1
        self._format_string = "{_num} x {_mult} = {_res}"
        self._cache = {}
        self._initialize_cache()

    def _initialize_cache(self):
        for i in range(1, self._limit + 1):
            self._cache[i] = None

    def _calculate_product(self, _multiplier):
        if self._cache[_multiplier] is None:
            self._cache[_multiplier] = self._number * _multiplier
        return self._cache[_multiplier]

    def _generate_entry(self):
        _product = self._calculate_product(self._current_multiplier)
        return self._format_string.format(_num=self._number, _mult=self._current_multiplier, _res=_product)

    def _append_entry(self, _entry):
        self._table_list.append(_entry)

    def _increment_multiplier(self):
        self._current_multiplier += 1

    def _is_limit_reached(self):
        return self._current_multiplier > self._limit

    def generate_table(self):
        while not self._is_limit_reached():
            _entry = self._generate_entry()
            self._append_entry(_entry)
            self._increment_multiplier()
        return self._table_list

def generate_times_table(number, limit):
    _generator = TimesTableGenerator(number, limit)
    return _generator.generate_table()

