class MatrixOperations:
    def __init__(self, _matrix1, _matrix2):
        self._matrix1 = _matrix1
        self._matrix2 = _matrix2
        self._rows = len(self._matrix1)
        self._cols = len(self._matrix1[0])
        self._result_matrix = []
        self._initialized = False

    def _validate_dimensions(self):
        if len(self._matrix1) != len(self._matrix2) or \
           len(self._matrix1[0]) != len(self._matrix2[0]):
            raise ValueError("Matrices must have the same dimensions.")
        self._initialized = True

    def _perform_subtraction(self):
        if not self._initialized:
            self._validate_dimensions()
        self._result_matrix = []
        for i in range(self._rows):
            _current_row = []
            for j in range(self._cols):
                _current_row.append(self._matrix1[i][j] - self._matrix2[i][j])
            self._result_matrix.append(_current_row)

    def _get_result(self):
        return self._result_matrix

    def _reset_state(self):
        self._result_matrix = []
        self._initialized = False

    def subtract(self):
        self._validate_dimensions()
        self._perform_subtraction()
        return self._get_result()

def matrix_subtract(matrix1, matrix2):
    _ops = MatrixOperations(matrix1, matrix2)
    return _ops.subtract()

