class WordReverser:
    def __init__(self, sentence):
        self._sentence = sentence
        self._words = []
        self._reversed_words = []
        self._result = ""
        self._separator = ' '
        self._initialized = False
        self._process()

    def _split_sentence(self):
        self._words = self._sentence.split(self._separator)

    def _reverse_word(self, word):
