    def _process(self):
        if not self._initialized:
            self._split_sentence()
            self._reverse_all_words()
            self._join_words()
            self._initialized = True

    def _get_result(self):
        return self._result

def reverse_each_word(sentence):
    _reverser = WordReverser(sentence)
    return _reverser._get_result()

