class StockCalculator:
    def __init__(self, _tax_rate=0.0):
        self._tax_rate = _tax_rate
        self._transaction_log = []
        self._current_transaction_id = 0
        self._last_calculated_profit = 0.0

    def _calculate_per_share_difference(self, _buy_price, _sell_price):
        return _sell_price - _buy_price

    def _apply_taxes(self, _gross_profit):
        return _gross_profit * (1 - self._tax_rate)

    def _log_transaction(self, _buy_price, _sell_price, _quantity, _profit_loss):
        self._current_transaction_id += 1
        _entry = {
            'id': self._current_transaction_id,
            'buy_price': _buy_price,
            'sell_price': _sell_price,
            'quantity': _quantity,
            'profit_loss': _profit_loss
        }
        self._transaction_log.append(_entry)

    def _update_last_profit(self, _profit):
        self._last_calculated_profit = _profit

    def calculate_stock_profit(self, buy_price, sell_price, quantity):
        _per_share_profit = self._calculate_per_share_difference(buy_price, sell_price)
        _gross_profit = _per_share_profit * quantity
        _net_profit = self._apply_taxes(_gross_profit)
        self._log_transaction(buy_price, sell_price, quantity, _net_profit)
        self._update_last_profit(_net_profit)
        return _net_profit

