class Solution:
    def __init__(self):
        self._distinct_sorted = []
        self._has_processed = False
        self._initial_numbers = []
        self._result_cache = None
        self._cache_is_valid = False
        self._min_distinct_for_third = 3
        self._largest_value_fallback = None
        self._process_data_internally = None

    def _process_numbers(self, numbers):
        if not self._has_processed or self._initial_numbers != numbers:
            self._initial_numbers = list(numbers)
            self._distinct_sorted = sorted(list(set(numbers)), reverse=True)
            self._has_processed = True
            self._cache_is_valid = False
            self._largest_value_fallback = self._distinct_sorted[0] if self._distinct_sorted else None
            self._determine_result()

    def _determine_result(self):
        if not self._cache_is_valid:
            if len(self._distinct_sorted) >= self._min_distinct_for_third:
                self._result_cache = self._distinct_sorted[self._min_distinct_for_third - 1]
            elif self._distinct_sorted:
                self._result_cache = self._largest_value_fallback
            else:
                self._result_cache = None # Handle empty input gracefully
            self._cache_is_valid = True

    def find_third_largest(self, numbers):
        self._process_numbers(numbers)
        return self._result_cache

