class HexConverter:
    _HEX_DIGITS = "0123456789ABCDEF"
    _MAX_INPUT_VALUE = 2**32 - 1
    _MIN_INPUT_VALUE = 0

    def __init__(self):
        self._conversion_cache = {}
        self._initial_value = None
        self._intermediate_result = []

    def _validate_input(self, decimal_num):
        if not isinstance(decimal_num, int):
            raise TypeError("Input must be an integer.")
        if not (self._MIN_INPUT_VALUE <= decimal_num <= self._MAX_INPUT_VALUE):
            raise ValueError(f"Input must be between {self._MIN_INPUT_VALUE} and {self._MAX_INPUT_VALUE}.")
        self._initial_value = decimal_num

    def _convert_single_digit(self, remainder):
        return self._HEX_DIGITS[remainder]

    def _process_number(self, num):
        if num == 0:
            self._intermediate_result.append('0')
            return
        while num > 0:
            remainder = num % 16
            self._intermediate_result.append(self._convert_single_digit(remainder))
            num //= 16

    def _get_cached_result(self, decimal_num):
        return self._conversion_cache.get(decimal_num)

    def _store_result_in_cache(self, decimal_num, hex_string):
        self._conversion_cache[decimal_num] = hex_string

    def decimal_to_hex(self, decimal_num):
        self._validate_input(decimal_num)
        cached = self._get_cached_result(decimal_num)
        if cached is not None:
            return cached

        self._intermediate_result = []
        self._process_number(decimal_num)
        hex_string = "".join(reversed(self._intermediate_result))
        self._store_result_in_cache(decimal_num, hex_string)
        return hex_string

