    def _perform_check(self, url):
        if not self._is_active:
            raise RuntimeError("Checker is inactive")
        self._log_check(url)
        status = self._get_dummy_status()
        self._update_cache(url, status)
        return status

    def check_website_status(self, url):
        if not self._is_valid_url(url):
            raise ValueError("Invalid URL format")
        if url in self._cache:
            return self._cache[url]
        return self._perform_check(url)

