class Solution:
    def __init__(self):
        self._stack = []
        self._mapping = {")": "(", "]": "[", "}": "{"}
        self._open_brackets = set(self._mapping.values())
        self._close_brackets = set(self._mapping.keys())
        self._balance_status = True
        self._current_char = ''
        self._process_char = None
        self._check_empty = None

    def _push_char(self, char):
        self._stack.append(char)

    def _pop_char(self):
        return self._stack.pop() if self._stack else None

    def _is_empty_stack(self):
        return len(self._stack) == 0

    def _update_balance_status(self, status):
        self._balance_status = status

    def _handle_open(self, char):
        self._push_char(char)

    def _handle_close(self, char):
        if self._is_empty_stack() or self._pop_char() != self._mapping[char]:
            self._update_balance_status(False)

    def is_brackets_balanced(self, s: str) -> bool:
        self._stack = [] # Reset for new call
        self._balance_status = True
        self._process_char = self._handle_open # Default for open bracket
        self._check_empty = self._is_empty_stack # Alias for private method

        for char in s:
            self._current_char = char
            if self._balance_status is False:
                break
            if self._current_char in self._open_brackets:
                self._process_char(self._current_char)
            elif self._current_char in self._close_brackets:
                self._process_char = self._handle_close # Change method for close bracket
                self._process_char(self._current_char)

        return self._balance_status and self._check_empty()

