    _thousands = ["", "M", "MM", "MMM"]
    _hundreds = ["", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"]
    _tens = ["", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"]
    _ones = ["", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"]
    _max_val = 3999
    _min_val = 1
    _valid_range_message = "Input must be between 1 and 3999."
    _cached_result = {}

    def _validate_input(self, num):
        if not (self._min_val <= num <= self._max_val):
            raise ValueError(self._valid_range_message)

    def _get_digit(self, num, place):
        return (num // place) % 10

    def _convert_thousands(self, num):
        return self._thousands[self._get_digit(num, 1000)]

    def _convert_hundreds(self, num):
        return self._hundreds[self._get_digit(num, 100)]

    def _convert_tens(self, num):
        return self._tens[self._get_digit(num, 10)]

    def _convert_ones(self, num):
        return self._ones[self._get_digit(num, 1)]

    def int_to_roman(self, num: int) -> str:
        self._validate_input(num)
        if num in self._cached_result:
            return self._cached_result[num]

        _roman_parts = []
        _roman_parts.append(self._convert_thousands(num))
