class RomanConverter:
    __thousands = ["", "M", "MM", "MMM"]
    __hundreds = ["", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"]
    __tens = ["", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"]
    __ones = ["", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"]
    __max_val = 3999
    __min_val = 1
    __valid_range_message = "Input must be between 1 and 3999."
    __cached_result = {}

    def __validate_input(self, num):
        if not (self.__min_val <= num <= self.__max_val):
            raise ValueError(self.__valid_range_message)

    def __get_digit(self, num, place):
        return (num // place) % 10

    def __convert_thousands(self, num):
        return self.__thousands[self.__get_digit(num, 1000)]

    def __convert_hundreds(self, num):
        return self.__hundreds[self.__get_digit(num, 100)]

    def __convert_tens(self, num):
        return self.__tens[self.__get_digit(num, 10)]

    def __convert_ones(self, num):
        return self.__ones[self.__get_digit(num, 1)]

    def int_to_roman(self, num: int) -> str:
        self.__validate_input(num)
        if num in self.__cached_result:
            return self.__cached_result[num]

        _roman_parts = []
        _roman_parts.append(self.__convert_thousands(num))
        _roman_parts.append(self.__convert_hundreds(num))
        _roman_parts.append(self.__convert_tens(num))
        _roman_parts.append(self.__convert_ones(num))

        _result = "".join(_roman_parts)
