class ImageProcessor:
    def __init__(self):
        self._image_data = None
        self._grayscale_data = None
        self._width = 0
        self._height = 0
        self._average_method = self._calculate_average
        self._pixel_cache = {}
        self._processing_active = False
        self._validation_enabled = True

    def _set_image(self, image_matrix):
        if self._validation_enabled and not self._is_valid_image(image_matrix):
            raise ValueError("Invalid image matrix format.")
        self._image_data = image_matrix
        self._height = len(image_matrix)
        self._width = len(image_matrix[0]) if self._height > 0 else 0
        self._pixel_cache.clear()
        self._grayscale_data = None

    def _is_valid_image(self, matrix):
        if not isinstance(matrix, list) or not all(isinstance(row, list) for row in matrix):
            return False
        if not matrix:
            return True
        row_len = len(matrix[0])
        if not all(len(row) == row_len for row in matrix):
            return False
        return all(isinstance(pixel, list) and len(pixel) == 3 and
                   all(0 <= c <= 255 for c in pixel)
                   for row in matrix for pixel in row)

    def _calculate_average(self, r, g, b):
        return round((r + g + b) / 3)

    def _process_pixel(self, pixel):
        pixel_tuple = tuple(pixel)
        if pixel_tuple in self._pixel_cache:
            return self._pixel_cache[pixel_tuple]

        r, g, b = pixel
        grayscale_value = self._average_method(r, g, b)
        self._pixel_cache[pixel_tuple] = grayscale_value
        return grayscale_value

    def _convert_row_to_grayscale(self, row):
        return [self._process_pixel(pixel) for pixel in row]

    def _generate_grayscale_image(self):
        self._processing_active = True
        grayscale_matrix = [self._convert_row_to_grayscale(row) for row in self._image_data]
        self._processing_active = False
        return grayscale_matrix

    def to_grayscale(self, image_matrix):
        self._set_image(image_matrix)
        self._grayscale_data = self._generate_grayscale_image()
        return self._grayscale_data

def to_grayscale(image_matrix):
    processor = ImageProcessor()
    return processor.to_grayscale(image_matrix)

