        self._input_data_processed = True
        self._last_processed_list = numbers[:]

    def calculate_mode(self, numbers):
        _tuple_numbers = tuple(numbers)
        if _tuple_numbers in self._results_cache:
            return self._results_cache[_tuple_numbers]

        self._process_list(numbers)
        self._calculation_id_counter += 1
        _final_mode = self._current_mode_candidate
        self._results_cache[_tuple_numbers] = _final_mode
        return _final_mode

