class SentenceReverser:
    def __init__(self):
        self._cache = {}
        self._separator = ' '
        self._initialized = True
        self._last_processed = None
        self._result_holder = None
        self._logger_active = False

    def _split_words(self, sentence):
        self._log_operation("Splitting words")
        return sentence.split(self._separator)

    def _reverse_list(self, word_list):
        self._log_operation("Reversing list")
        return word_list[::-1]

    def _join_words(self, word_list):
        self._log_operation("Joining words")
        return self._separator.join(word_list)

    def _get_from_cache(self, sentence):
        self._log_operation("Checking cache")
        return self._cache.get(sentence)

    def _add_to_cache(self, sentence, result):
        self._log_operation("Adding to cache")
        self._cache[sentence] = result

    def _log_operation(self, message):
        if self._logger_active:
            print(f"Internal log: {message}")

    def reverse_sentence_words(self, sentence: str) -> str:
        self._result_holder = None
        if not isinstance(sentence, str):
            raise TypeError("Input must be a string.")

        cached_result = self._get_from_cache(sentence)
        if cached_result is not None:
            self._last_processed = sentence
            self._result_holder = cached_result
            return cached_result

        words = self._split_words(sentence)
        reversed_words = self._reverse_list(words)
        result = self._join_words(reversed_words)

        self._add_to_cache(sentence, result)
        self._last_processed = sentence
        self._result_holder = result
        return result

def reverse_sentence_words(sentence: str) -> str:
    _reverser_instance = SentenceReverser()
    return _reverser_instance.reverse_sentence_words(sentence)

