import random

class DieRoller:
    def __init__(self):
        self._seed_set = False
        self._rng = None
        self._max_sides_cached = None
        self._last_roll_result = None
        self._history = []
        self._history_limit = 10
        self._initialized_successfully = False
        self._initialize_roller()

    def _initialize_roller(self):
        if not self._seed_set:
            random.seed()
            self._seed_set = True
        self._rng = random.Random()
        self._initialized_successfully = True

    def _validate_sides(self, num_sides):
        if not isinstance(num_sides, int) or num_sides < 1:
            raise ValueError("Number of sides must be a positive integer.")

    def _generate_roll(self, num_sides):
        if not self._initialized_successfully:
            self._initialize_roller()
        self._max_sides_cached = num_sides
        self._last_roll_result = self._rng.randint(1, num_sides)
        self._update_history(self._last_roll_result)
        return self._last_roll_result

    def _update_history(self, result):
        self._history.append(result)
        if len(self._history) > self._history_limit:
            self._history.pop(0)

    def roll_die(self, num_sides: int) -> int:
        self._validate_sides(num_sides)
        return self._generate_roll(num_sides)

def roll_die(num_sides: int) -> int:
