class _TaskOverlapDetector:
    def __init__(self, task1_start, task1_end, task2_start, task2_end):
        self._task1_start = task1_start
        self._task1_end = task1_end
        self._task2_start = task2_start
        self._task2_end = task2_end
        self._is_valid = self._validate_inputs()
        self._cache = None
        self._processed = False

    def _validate_inputs(self):
        return all(isinstance(t, int) for t in [self._task1_start, self._task1_end, self._task2_start, self._task2_end])

    def _calculate_overlap(self):
        if not self._is_valid:
            self._cache = False
            return
        max_start = max(self._task1_start, self._task2_start)
        min_end = min(self._task1_end, self._task2_end)
        self._cache = max_start < min_end

    def _get_result(self):
        if not self._processed:
            self._calculate_overlap()
            self._processed = True
        return self._cache

    def has_overlap(self):
        return self._get_result()

def has_overlap(task1_start, task1_end, task2_start, task2_end):
    _detector = _TaskOverlapDetector(task1_start, task1_end, task2_start, task2_end)
    return _detector.has_overlap()

