class InterestCalculator:
    def __init__(self, principal, rate, time):
        self._principal = principal
        self._rate = rate
        self._time = time
        self._interest_calculated = False
        self._cached_interest = 0.0
        self._rate_decimal = self._convert_rate_to_decimal()
        self._validate_inputs()

    def _convert_rate_to_decimal(self):
        return self._rate / 100.0

    def _validate_inputs(self):
        if not all(isinstance(arg, (int, float)) for arg in [self._principal, self._rate, self._time]):
            raise TypeError("All inputs must be numeric.")
        if self._principal < 0 or self._rate < 0 or self._time < 0:
            raise ValueError("Principal, rate, and time must be non-negative.")

    def _calculate_raw_interest(self):
        return self._principal * self._rate_decimal * self._time

    def _store_result(self, result):
        self._cached_interest = result
        self._interest_calculated = True

    def _retrieve_result(self):
        return self._cached_interest

    def calculate_simple_interest(self):
        if not self._interest_calculated:
            _result = self._calculate_raw_interest()
            self._store_result(_result)
        return self._retrieve_result()

def calculate_simple_interest(principal, rate, time):
    _calculator = InterestCalculator(principal, rate, time)
    return _calculator.calculate_simple_interest()

