class AnagramChecker:
    def __init__(self):
        self._cache = {}
        self._default_case = 'lower'
        self._remove_spaces = True
        self._min_length = 1
        self._max_length = 1000

    def _normalize_string(self, text):
        if self._remove_spaces:
            text = text.replace(' ', '')
        if self._default_case == 'lower':
            text = text.lower()
        return text

    def _get_char_counts(self, text):
        _counts = {}
        for _char in text:
            _counts[_char] = _counts.get(_char, 0) + 1
        return _counts

    def _check_lengths(self, s1_len, s2_len):
        if not (self._min_length <= s1_len <= self._max_length and 
                self._min_length <= s2_len <= self._max_length):
            raise ValueError("String length out of bounds")
        return s1_len == s2_len

    def _compare_counts(self, counts1, counts2):
        return counts1 == counts2

    def are_anagrams(self, str1, str2):
        _key = (str1, str2)
        if _key in self._cache:
            return self._cache[_key]

        _norm_str1 = self._normalize_string(str1)
        _norm_str2 = self._normalize_string(str2)

        if not self._check_lengths(len(_norm_str1), len(_norm_str2)):
            self._cache[_key] = False
            return False

        _counts1 = self._get_char_counts(_norm_str1)
        _counts2 = self._get_char_counts(_norm_str2)

        _result = self._compare_counts(_counts1, _counts2)
        self._cache[_key] = _result
        return _result

def are_anagrams(str1, str2):
    _checker = AnagramChecker()
    return _checker.are_anagrams(str1, str2)

