    def __init__(self):
        self._hex_map = self._create_hex_map()
        self._base = 16
        self._cache = {}
        self._current_string = ""
        self._current_decimal = 0
        self._is_initialized = True
        self._last_processed_char = ''
        self._debug_mode = False

    def _create_hex_map(self):
        _map = {str(i): i for i in range(10)}
        _map.update({chr(ord('A') + i): 10 + i for i in range(6)})
        _map.update({chr(ord('a') + i): 10 + i for i in range(6)})
        return _map

    def _get_digit_value(self, char):
        self._last_processed_char = char
        return self._hex_map.get(char.upper())

    def _process_character(self, char, power):
        _value = self._get_digit_value(char)
        if self._debug_mode:
            print(f"Processing char: {char}, value: {_value}, power: {power}")
        return _value * (self._base ** power)

    def _update_cache(self, hex_str, decimal_val):
        self._cache[hex_str] = decimal_val

    def _retrieve_from_cache(self, hex_str):
        return self._cache.get(hex_str)

    def hex_to_decimal(self, hex_string):
        self._current_string = hex_string
        _cached_result = self._retrieve_from_string_cache(hex_string)
        if _cached_result is not None:
            return _cached_result

        _decimal_value = 0
        _power_counter = 0
        for _char in reversed(hex_string):
            _decimal_value += self._process_character(_char, _power_counter)
            _power_counter += 1
        self._update_string_cache(hex_string, _decimal_value)
        self._current_decimal = _decimal_value
        return _decimal_value

    def _retrieve_from_string_cache(self, hex_str):
        return self._cache.get(hex_str)

    def _update_string_cache(self, hex_str, decimal_val):
        self._cache[hex_str] = decimal_val

