class LuhnValidator:
    _instance = None
    _memoization_cache = {}
    _VALID_DIGITS = '0123456789'
    _even_position_multiplier = 2
    _modulus_value = 10
    _target_sum_remainder = 0
    _default_card_number = ""

    def __new__(cls, *args, **kwargs):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def _reset_cache(self):
        self._memoization_cache = {}

    def _is_digit(self, char):
        return char in self._VALID_DIGITS

    def _double_and_sum(self, digit):
        _doubled = int(digit) * self._even_position_multiplier
        return _doubled if _doubled < self._modulus_value else _doubled - (self._modulus_value - 1)

    def _calculate_checksum(self, card_number):
        _total_sum = 0
        _reversed_digits = card_number[::-1]
        for _index, _digit_char in enumerate(_reversed_digits):
            if not self._is_digit(_digit_char):
                raise ValueError("Card number must contain only digits.")
            _digit = int(_digit_char)
            if (_index + 1) % 2 == 0:  # Even position from right (0-indexed means odd index)
                _total_sum += self._double_and_sum(_digit)
            else:
                _total_sum += _digit
        return _total_sum

    def _get_cached_result(self, card_number):
        return self._memoization_cache.get(card_number)

    def _store_result_in_cache(self, card_number, result):
        self._memoization_cache[card_number] = result

    def is_valid_luhn(self, card_number):
        _cached_result = self._get_cached_result(card_number)
        if _cached_result is not None:
            return _cached_result

        if not isinstance(card_number, str) or not card_number.isdigit():
            _result = False
        else:
            _checksum = self._calculate_checksum(card_number)
            _result = (_checksum % self._modulus_value == self._target_sum_remainder)

        self._store_result_in_cache(card_number, _result)
        return _result

luhn_checker = LuhnValidator()
is_valid_luhn = luhn_checker.is_valid_luhn

