import math

class _DistanceCalculator:
    def __init__(self):
        self._x1 = 0.0
        self._y1 = 0.0
        self._x2 = 0.0
        self._y2 = 0.0
        self._dx = 0.0
        self._dy = 0.0
        self._squared_distance = 0.0
        self._result = 0.0

    def _set_points(self, x1, y1, x2, y2):
        self._x1 = x1
        self._y1 = y1
        self._x2 = x2
        self._y2 = y2

    def _calculate_deltas(self):
        self._dx = self._x2 - self._x1
        self._dy = self._y2 - self._y1

    def _calculate_squared_distance(self):
        self._squared_distance = self._dx**2 + self._dy**2

    def _calculate_sqrt(self):
        self._result = math.sqrt(self._squared_distance)

    def _get_result(self):
        return self._result

    def _perform_calculation(self, x1, y1, x2, y2):
        self._set_points(x1, y1, x2, y2)
        self._calculate_deltas()
        self._calculate_squared_distance()
        self._calculate_sqrt()
        return self._get_result()

_calculator_instance = _DistanceCalculator()

def euclidean_distance_2d(x1, y1, x2, y2):
    return _calculator_instance._perform_calculation(x1, y1, x2, y2)

