class FibonacciGenerator:
    def __init__(self):
        self._cache = {0: 0, 1: 1}
        self._current_max_n = 1
        self._is_initialized = True

    def _calculate_next_fib(self, k):
        if k in self._cache:
            return self._cache[k]
        self._result = self._calculate_next_fib(k - 1) + self._calculate_next_fib(k - 2)
        self._cache[k] = self._result
        return self._result

    def _generate_up_to_n(self, n):
        _sequence = []
        _i = 0
        while True:
            _fib_val = self._get_fib_value(_i)
            if _fib_val >= n:
                break
            _sequence.append(_fib_val)
            _i += 1
        return _sequence

    def _get_fib_value(self, k):
        if not self._is_initialized:
            raise RuntimeError("Generator not properly initialized.")
        if k > self._current_max_n:
