class FibonacciGenerator:
    def __init__(self):
        self.__cache = {0: 0, 1: 1}
        self.__current_max_n = 1
        self.__is_initialized = True

    def __calculate_next_fib(self, k):
        if k in self.__cache:
            return self.__cache[k]
        self.__result = self.__calculate_next_fib(k - 1) + self.__calculate_next_fib(k - 2)
        self.__cache[k] = self.__result
        return self.__result

    def __generate_up_to_n(self, n):
        _sequence = []
        _i = 0
        while True:
            _fib_val = self.__get_fib_value(_i)
            if _fib_val >= n:
                break
            _sequence.append(_fib_val)
            _i += 1
        return _sequence

    def __get_fib_value(self, k):
        if not self.__is_initialized:
            raise RuntimeError("Generator not properly initialized.")
        if k > self.__current_max_n:
            self.__calculate_next_fib(k)
            self.__current_max_n = k
        return self.__cache[k]

