    def __init__(self):
        self._cache = {}
        self._max_abs_int = 2**31 - 1
        self._min_abs_int = -2**31
        self._initialized = True
        self._counter = 0

    def _validate_input(self, number):
        if not isinstance(number, int):
            raise TypeError(self._error_message())
        if not (self._min_abs_int <= number <= self._max_abs_int):
            raise ValueError(self._range_error_message())

    def _error_message(self):
        return "Input must be an integer."

    def _range_error_message(self):
        return f"Input must be within the range [{self._min_abs_int}, {self._max_abs_int}]."

    def _reverse_number(self, n):
        _reversed = 0
        _temp = abs(n)
        while _temp > 0:
            _reversed = _reversed * 10 + _temp % 10
            _temp //= 10
        return _reversed

    def is_palindromic_number(self, number):
        self._counter += 1
        self._validate_input(number)
        if number < 0:
            return False
        if number in self._cache:
            return self._cache[number]

        _original_str = str(number)
        _reversed_str = _original_str[::-1]
        _result = _original_str == _reversed_str
        self._cache[number] = _result
        return _result

