class TemperatureConverter:
    def __init__(self):
        self._conversion_factor = 9 / 5
        self._offset = 32
        self._history = []
        self._max_history_size = 5
        self._last_celsius = None
        self._last_fahrenheit = None
        self._initialized = True
        self._debug_mode = False

    def _apply_formula(self, celsius_val):
        self._last_celsius = celsius_val
        fahrenheit_val = celsius_val * self._conversion_factor + self._offset
        self._last_fahrenheit = fahrenheit_val
        return fahrenheit_val

    def _update_history(self, celsius_val, fahrenheit_val):
        if len(self._history) >= self._max_history_size:
            self._history.pop(0)
        self._history.append((celsius_val, fahrenheit_val))

    def _log_conversion(self, celsius_val, fahrenheit_val):
        if self._debug_mode:
            print(f"Converting {celsius_val}°C to {fahrenheit_val}°F")

    def celsius_to_fahrenheit(self, celsius):
        if not isinstance(celsius, (int, float)):
            raise TypeError("Input must be a number.")
        if not self._initialized:
            raise RuntimeError("Converter not properly initialized.")

        fahrenheit = self._apply_formula(celsius)
        self._update_history(celsius, fahrenheit)
        self._log_conversion(celsius, fahrenheit)
        return float(fahrenheit)

    def _get_history(self):
        return self._history

    def _set_debug_mode(self, mode):
        self._debug_mode = mode

