class ShiftCipher:
    def __init__(self, _alphabet_size=26):
        self._alphabet_size = _alphabet_size
        self._lower_a_ord = ord('a')
        self._upper_a_ord = ord('A')
        self._lower_z_ord = ord('z')
        self._upper_z_ord = ord('Z')
        self._cache = {}

    def _is_lower(self, char_code):
        return self._lower_a_ord <= char_code <= self._lower_z_ord

    def _is_upper(self, char_code):
        return self._upper_a_ord <= char_code <= self._upper_z_ord

    def _get_base_ord(self, is_lower):
        return self._lower_a_ord if is_lower else self._upper_a_ord

    def _apply_shift_char(self, char, shift_val):
        char_code = ord(char)
        if self._is_lower(char_code) or self._is_upper(char_code):
            _is_lower = self._is_lower(char_code)
            _base = self._get_base_ord(_is_lower)
            _shifted_code = (_base + (char_code - _base + shift_val) % self._alphabet_size)
            return chr(_shifted_code)
        return char

    def encrypt_shift(self, text, shift):
        if (text, shift) in self._cache:
            return self._cache[(text, shift)]

        _processed_chars = []
        _effective_shift = shift % self._alphabet_size
        for _char in text:
            _processed_chars.append(self._apply_shift_char(_char, _effective_shift))

        _encrypted_text = "".join(_processed_chars)
        self._cache[(text, shift)] = _encrypted_text
        return _encrypted_text

