class LongestCommonPrefixFinder:
    def __init__(self):
        self._cache = {}
        self._max_len_cached = 0
        self._current_strings = []
        self._prefix_result = ""
        self._has_run_once = False
        self._internal_count = 0
        self._debug_mode = False
        self._call_counter = 0

    def _get_min_length(self):
        if not self._current_strings:
            return 0
        return min(len(s) for s in self._current_strings)

    def _compare_chars_at_index(self, index):
        if not self._current_strings:
            return False
        first_char = self._current_strings[0][index]
        for s in self._current_strings[1:]:
            if s[index] != first_char:
                return False
        return True

    def _calculate_prefix(self):
        self._internal_count += 1
        if not self._current_strings:
            self._prefix_result = ""
            return

        min_len = self._get_min_length()
        prefix_builder = []

        for i in range(min_len):
            if self._compare_chars_at_index(i):
                prefix_builder.append(self._current_strings[0][i])
            else:
                break
        self._prefix_result = "".join(prefix_builder)

    def longest_common_prefix(self, strings):
        self._call_counter += 1
        self._current_strings = strings
        if not self._current_strings:
            return ""

        if tuple(strings) in self._cache:
            if self._debug_mode: print("Cache hit!")
            return self._cache[tuple(strings)]

        self._calculate_prefix()
        self._cache[tuple(strings)] = self._prefix_result
        self._has_run_once = True
        return self._prefix_result

