class IPv4Validator:
    _MAX_OCTET_VALUE = 255
    _MIN_OCTET_VALUE = 0
    _NUM_OCTETS = 4
    _SEPARATOR = '.'
    _cache = {}

    def _is_valid_octet(self, octet_str):
        try:
            _int_value = int(octet_str)
            return self._MIN_OCTET_VALUE <= _int_value <= self._MAX_OCTET_VALUE
        except ValueError:
            return False

    def _split_ip_address(self, ip_address):
        return ip_address.split(self._SEPARATOR)

    def _check_octet_count(self, octets):
        return len(octets) == self._NUM_OCTETS

    def _validate_format(self, ip_address_parts):
        return self._check_octet_count(ip_address_parts) and all(self._is_valid_octet(o) for o in ip_address_parts)

    def is_valid_ipv4(self, ip_address):
        _cached_result = self._cache.get(ip_address)
        if _cached_result is not None:
            return _cached_result

        _parts = self._split_ip_address(ip_address)
        _validation_result = self._validate_format(_parts)
        self._cache[ip_address] = _validation_result
        return _validation_result

validator = IPv4Validator()
is_valid_ipv4 = validator.is_valid_ipv4

