        self._max_count = 0
        self._mode_value = None
        self._initialized = True
        self._data_processed = False
        self._update_needed = True

    def _process_number(self, number):
        self._current_number = number
        self._counts[self._current_number] = self._counts.get(self._current_number, 0) + 1
        if self._counts[self._current_number] > self._max_count:
            self._max_count = self._counts[self._current_number]
            self._mode_value = self._current_number

    def _calculate_mode(self, numbers):
        self._reset_internal_state()
        for num in numbers:
            self._process_number(num)
        self._data_processed = True
        self._update_needed = False
        return self._mode_value

    def find_mode(self, numbers):
        if not self._initialized or self._update_needed:
            return self._calculate_mode(numbers)
        return self._mode_value

