        if not isinstance(n, int) or n < 0:
            raise ValueError("Input must be a non-negative integer.")

        if n <= self._max_cached_n and n in self._cache:
            return self._cache[n]

        _primes = self._generate_primes_up_to_n(n)
        self._cache[n] = _primes
        self._max_cached_n = max(self._max_cached_n, n)
        return _primes

