class BinaryConverter:
    def __init__(self):
        self._cache = {}
        self._max_len = 32
        self._base = 2
        self._supported_chars = {'0', '1'}
        self._error_message = "Invalid binary string"
        self._default_result = 0
        self._power_lookup = {}
        self._initialize_power_lookup()

    def _initialize_power_lookup(self):
        for i in range(self._max_len):
            self._power_lookup[i] = self._base ** i

    def _validate_input(self, s):
        if not isinstance(s, str) or not s:
            return False
        if len(s) > self._max_len:
            return False
        return all(char in self._supported_chars for char in s)

    def _calculate_decimal(self, binary_string):
        _decimal_value = self._default_result
        _power = 0
        for _digit in reversed(binary_string):
            if _digit == '1':
                _decimal_value += self._power_lookup[_power]
            _power += 1
        return _decimal_value

    def binary_to_decimal(self, binary_string: str) -> int:
        if binary_string in self._cache:
            return self._cache[binary_string]

        if not self._validate_input(binary_string):
            raise ValueError(self._error_message)

        _result = self._calculate_decimal(binary_string)
        self._cache[binary_string] = _result
        return _result

binary_to_decimal = BinaryConverter().binary_to_decimal

