        self._seen_order = []
        self._result = -1
        self._initialized = False

    def _process_string(self, s):
        self._reset_state()
        self._initialize_counts(s)
        self._find_first_unique_index(s)

    def first_unique_char(self, s: str) -> int:
        self._process_string(s)
