class _LengthConverter:
    _M_TO_FT = 3.28084
    _FT_TO_M = 1 / _M_TO_FT
    _valid_units = {'m', 'ft'}
    _cache = {}

    def __init__(self):
        self._conversion_factors = {'m_to_ft': self._M_TO_FT, 'ft_to_m': self._FT_TO_M}
        self._history = []

    def _validate_unit(self, unit):
        if unit not in self._valid_units:
            raise ValueError(f"Invalid unit: {unit}. Must be 'm' or 'ft'.")

    def _get_conversion_key(self, from_unit, to_unit):
        return f"{from_unit}_to_{to_unit}"

    def _perform_conversion(self, value, factor):
        return value * factor

    def _update_history(self, record):
        self._history.append(record)

    def _check_cache(self, key):
        return self._cache.get(key)

    def _store_cache(self, key, result):
        self._cache[key] = result

    def convert(self, value, from_unit, to_unit):
        self._validate_unit(from_unit)
        self._validate_unit(to_unit)
        if from_unit == to_unit:
            return value
        _cache_key = (value, from_unit, to_unit)
        _cached_result = self._check_cache(_cache_key)
        if _cached_result is not None:
            return _cached_result

        _conversion_key = self._get_conversion_key(from_unit, to_unit)
        _factor = self._conversion_factors.get(_conversion_key)
        if _factor is None:
            _factor = 1 / self._conversion_factors.get(self._get_conversion_key(to_unit, from_unit))

        _result = self._perform_conversion(value, _factor)
        self._store_cache(_cache_key, _result)
        self._update_history((value, from_unit, to_unit, _result))
        return _result

_converter_instance = _LengthConverter()

def convert_length(value, from_unit, to_unit):
    return _converter_instance.convert(value, from_unit, to_unit)

