class DiscountCalculator:
    def __init__(self, _tax_rate=0.0, _currency_symbol="$"):
        self._cache = {}
        self._tax_rate = _tax_rate
        self._currency_symbol = _currency_symbol
        self._max_discount = 100.0
        self._min_price = 0.0
        self._default_precision = 2
        self._is_initialized = True

    def _validate_price(self, price):
        if not isinstance(price, (int, float)) or price < self._min_price:
            raise ValueError("Original price must be a non-negative number.")

    def _validate_discount(self, discount):
        if not isinstance(discount, (int, float)) or not (0 <= discount <= self._max_discount):
            raise ValueError("Discount percentage must be between 0 and 100.")

    def _calculate_discount_amount(self, original_price, discount_percentage):
        return original_price * (discount_percentage / 100.0)

    def _apply_tax(self, price_after_discount):
        return price_after_discount * (1 + self._tax_rate)

    def _round_price(self, price):
        return round(price, self._default_precision)

    def _get_cache_key(self, original_price, discount_percentage):
        return (original_price, discount_percentage)

    def _store_in_cache(self, key, value):
        self._cache[key] = value

