class UniqueCharChecker:
    def __init__(self, _initial_string=None):
        self._character_set = set()
        self._input_string = _initial_string
        self._is_initialized = True
        self._last_result = None
        self._cache_enabled = True
        self._validation_error = None
        self._processed_count = 0
        self._max_len_for_cache = 100

    def _reset_state(self):
        self._character_set.clear()
        self._last_result = None
        self._validation_error = None

    def _validate_input(self, s):
        if not isinstance(s, str):
            self._validation_error = "Input must be a string."
            return False
        return True

    def _process_string_internal(self, s):
        if not self._validate_input(s):
            return False

        if self._cache_enabled and s == self._input_string and self._last_result is not None:
            return self._last_result

        self._reset_state()
        self._input_string = s
        self._processed_count += 1

        for _char in s:
            if _char in self._character_set:
                self._last_result = False
                return False
            self._character_set.add(_char)

        self._last_result = True
        return True

    def _get_error_message(self):
        return self._validation_error

    def _disable_cache(self):
        self._cache_enabled = False

    def _check_length_for_caching(self, s):
        return len(s) <= self._max_len_for_cache

    def has_all_unique_chars(self, s):
        if not self._check_length_for_caching(s):
            self._disable_cache() # Temporarily disable for very long strings

        _result = self._process_string_internal(s)
        if self._validation_error:
            raise ValueError(self._get_error_message())
        return _result

