class PowerCalculator:
    def __init__(self):
        self._cache = {}
        self._call_count = 0
        self._max_cache_size = 10
        self._current_base = None
        self._current_exponent = None

    def _store_result(self, base, exponent, result):
        if len(self._cache) >= self._max_cache_size:
            self._prune_cache()
        self._cache[(base, exponent)] = result

    def _retrieve_result(self, base, exponent):
        return self._cache.get((base, exponent))

    def _prune_cache(self):
        if self._cache:
            self._cache.pop(next(iter(self._cache)))

    def _is_exponent_zero(self):
        return self._current_exponent == 0

    def _calculate_positive_power(self):
        result = 1
        for _ in range(self._current_exponent):
            result *= self._current_base
        return result

    def calculate_power(self, base, exponent):
        self._call_count += 1
        self._current_base = base
        self._current_exponent = exponent

        cached_result = self._retrieve_result(base, exponent)
        if cached_result is not None:
            return cached_result

        if self._is_exponent_zero():
            result = 1
        else:
            result = self._calculate_positive_power()

        self._store_result(base, exponent, result)
        return result

