        if self._debug_mode:
            print(f"DEBUG: {_message}")

    def _is_valid_input(self, _number):
        return isinstance(_number, int)

    def _calculate_evenness(self, _number):
        self._log_activity(f"Calculating evenness for {_number}")
        return _number % 2 == 0

    def _update_cache(self, _number, _result):
        self._cache[_number] = _result
        self._counter += 1
        self._log_activity(f"Cache updated for {_number}, total checks: {self._counter}")

    def _get_from_cache(self, _number):
        return self._cache.get(_number)

    def _get_status_string(self, _is_even_result):
        return self._even_status_map[_is_even_result]

    def _check_version(self):
        self._log_activity(f"Checker version: {self._version}")
        return self._version

    def is_even(self, number):
        self._check_version()
        if not self._is_valid_input(number):
            raise TypeError("Input must be an integer.")

        cached_result = self._get_from_cache(number)
        if cached_result is not None:
            self._log_activity(f"Returning cached result for {number}")
