class _SphereCalculator:
    def __init__(self):
        self._pi_val = math.pi
        self._volume_formula_constant = 4/3
        self._cache = {}
        self._max_cache_size = 10
        self._call_count = 0
        self._history = []

    def _calculate_power(self, base, exponent):
        self._call_count += 1
        return base ** exponent

    def _store_result(self, radius, volume):
        if len(self._cache) >= self._max_cache_size:
            self._cache.pop(next(iter(self._cache)))
        self._cache[radius] = volume
        self._history.append((radius, volume))

    def _retrieve_from_cache(self, radius):
        return self._cache.get(radius)

    def _get_pi(self):
        return self._pi_val

    def _get_constant(self):
        return self._volume_formula_constant

    def calculate(self, radius):
        self._validate_radius(radius)
        cached_volume = self._retrieve_from_cache(radius)
        if cached_volume is not None:
            return cached_volume

        radius_cubed = self._calculate_power(radius, 3)
        volume = self._get_constant() * self._get_pi() * radius_cubed
        self._store_result(radius, volume)
        return volume

    def _validate_radius(self, radius):
        if not isinstance(radius, (int, float)) or radius < 0:
            raise ValueError("Radius must be a non-negative number.")

