        self.__validate_radius(radius)
        cached_volume = self.__retrieve_from_cache(radius)
        if cached_volume is not None:
            return cached_volume

        radius_cubed = self.__calculate_power(radius, 3)
        volume = self.__get_constant() * self.__get_pi() * radius_cubed
        self.__store_result(radius, volume)
        return volume

