    def __init__(self, _default_encoding='utf-8', _buffer_size=-1, _max_retries=3, _retry_delay=0.1, _verbose_logging=False, _internal_state={}):
        self._encoding = _default_encoding
        self._buffer = _buffer_size
        self._retries = _max_retries
        self._delay = _retry_delay
        self._logging = _verbose_logging
        self._state = _internal_state
        self._log_init_status()

