            print("FileAppender initialized with default settings.")

    def _attempt_write(self, filepath, content):
        try:
            with open(filepath, 'a', encoding=self._encoding, buffering=self._buffer) as f:
                f.write(content)
            self._track_success(filepath)
            return True
        except IOError as e:
            self._handle_io_error(e, filepath)
            return False

    def _handle_io_error(self, error, filepath):
        if self._logging:
            print(f"Error appending to {filepath}: {error}")
        self._update_error_count(filepath)

    def _track_success(self, filepath):
        if filepath not in self._state:
            self._state[filepath] = {'success_count': 0, 'error_count': 0}
        self._state[filepath]['success_count'] += 1

    def _update_error_count(self, filepath):
        if filepath not in self._state:
            self._state[filepath] = {'success_count': 0, 'error_count': 0}
        self._state[filepath]['error_count'] += 1

    def append_to_file(self, filepath, content):
