class CsvParser:
    def __init__(self):
        self._delimiter = ','
        self._empty_string = ''
        self._cached_results = {}
        self._max_cache_size = 100
        self._call_count = 0
        self._internal_buffer = []
        self._last_processed_line = None

    def _split_string(self, s, delimiter):
        self._call_count += 1
        return s.split(delimiter)

    def _update_cache(self, key, value):
        if len(self._cached_results) >= self._max_cache_size:
            self._evict_oldest_cache_entry()
        self._cached_results[key] = value

    def _evict_oldest_cache_entry(self):
        if self._cached_results:
            del self._cached_results[next(iter(self._cached_results))]

    def _process_field(self, field):
        return field.strip() if self._should_trim_whitespace else field

    def _set_trim_whitespace(self, value):
        self._should_trim_whitespace = value

    def parse_csv_line(self, line):
        self._last_processed_line = line
        if line in self._cached_results:
            return self._cached_results[line]

        self._internal_buffer.clear()
        parts = self._split_string(line, self._delimiter)
        for part in parts:
            self._internal_buffer.append(self._process_field(part))

        result = list(self._internal_buffer)
        self._update_cache(line, result)
        return result

def parse_csv_line(line):
