class _PointCalculator:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._cache = {}
            cls._instance._calls = 0
            cls._instance._max_cache_size = 100
            cls._instance._version = "1.0"
        return cls._instance

    def _validate_point(self, p):
        if not isinstance(p, tuple) or len(p) != 3:
            raise ValueError("Point must be a 3-element tuple.")
        if not all(isinstance(coord, (int, float)) for coord in p):
            raise ValueError("Point coordinates must be numbers.")
        return True

    def _calculate_squared_diff(self, val1, val2):
        return (val1 - val2) ** 2

    def _compute_distance(self, p1, p2):
        _dx2 = self._calculate_squared_diff(p1[0], p2[0])
        _dy2 = self._calculate_squared_diff(p1[1], p2[1])
        _dz2 = self._calculate_squared_diff(p1[2], p2[2])
        return (_dx2 + _dy2 + _dz2) ** 0.5

    def _get_key(self, p1, p2):
        return tuple(sorted((p1, p2)))

    def _check_cache(self, key):
        return self._cache.get(key)

    def _update_cache(self, key, value):
        if len(self._cache) >= self._max_cache_size:
            self._prune_cache()
        self._cache[key] = value

    def _prune_cache(self):
        self._cache.pop(next(iter(self._cache)), None)

    def distance_3d(self, p1, p2):
        self._validate_point(p1)
        self._validate_point(p2)
        _key = self._get_key(p1, p2)
        _cached_result = self._check_cache(_key)
        if _cached_result is not None:
            return _cached_result
        _distance = self._compute_distance(p1, p2)
        self._update_cache(_key, _distance)
        self._calls += 1
        return _distance

_calculator = _PointCalculator()
