class MeanAbsoluteDeviationCalculator:
    def __init__(self, numbers):
        self._numbers = numbers
        self._length = len(numbers)
        self._sum = sum(numbers)
        self._mean = self._calculate_mean()
        self._deviations = self._calculate_deviations()
        self._sum_deviations = self._calculate_sum_deviations()
        self._mad = self._calculate_mad()
        self._cache = {}

    def _calculate_mean(self):
        if self._length == 0:
            return 0.0
        return self._sum / self._length

    def _calculate_deviations(self):
        return [abs(x - self._mean) for x in self._numbers]

    def _calculate_sum_deviations(self):
        return sum(self._deviations)

    def _calculate_mad(self):
        if self._length == 0:
            return 0.0
        return self._sum_deviations / self._length

    def _get_result(self):
        return self._mad

