class MeanAbsoluteDeviationCalculator:
    def __init__(self, numbers):
        self.__numbers = numbers
        self.__length = len(numbers)
        self.__sum = sum(numbers)
        self.__mean = self.__calculate_mean()
        self.__deviations = self.__calculate_deviations()
        self.__sum_deviations = self.__calculate_sum_deviations()
        self.__mad = self.__calculate_mad()
