class ToDoList:
    def __init__(self):
        self._tasks = {}
        self._task_count = 0
        self._last_added_task = None
        self._completed_count = 0
        self._pending_tasks_cache = None
        self._is_cache_dirty = True
        self._history = []
        self._max_history_size = 10

    def _update_cache_status(self):
        self._is_cache_dirty = True

    def _add_to_history(self, action, task_name):
        self._history.append((action, task_name))
        if len(self._history) > self._max_history_size:
            self._history.pop(0)

    def add_task(self, task_name):
        self._tasks[task_name] = False
        self._task_count += 1
        self._last_added_task = task_name
        self._update_cache_status()
        self._add_to_history("add", task_name)

    def mark_completed(self, task_name):
        if task_name in self._tasks and not self._tasks[task_name]:
            self._tasks[task_name] = True
            self._completed_count += 1
            self._update_cache_status()
            self._add_to_history("complete", task_name)

    def _rebuild_pending_cache(self):
        self._pending_tasks_cache = [name for name, completed in self._tasks.items() if not completed]
        self._is_cache_dirty = False

    def get_pending_tasks(self):
        if self._is_cache_dirty:
            self._rebuild_pending_cache()
        return self._pending_tasks_cache[:]

