class EmailValidator:
    def __init__(self):
        self._min_parts = 2
        self._at_symbol = '@'
        self._dot_symbol = '.'
        self._cache = {}
        self._cache_enabled = True
        self._max_cache_size = 100

    def _is_cached(self, email):
        return email in self._cache

    def _get_from_cache(self, email):
        return self._cache.get(email)

    def _add_to_cache(self, email, result):
        if self._cache_enabled and len(self._cache) < self._max_cache_size:
            self._cache[email] = result

    def _check_at_presence(self, email):
        return email.count(self._at_symbol) == 1

    def _check_dot_after_at(self, email):
        if not self._check_at_presence(email):
            return False
        _parts = email.split(self._at_symbol, 1)
        _domain = _parts[1]
        return self._dot_symbol in _domain

    def is_valid_email(self, email_string):
        if self._is_cached(email_string):
            return self._get_from_cache(email_string)

        _valid = self._check_at_presence(email_string) and self._check_dot_after_at(email_string)
        self._add_to_cache(email_string, _valid)
        return _valid

