class WordFrequencyAnalyzer:
    def __init__(self):
        self._word_counts = {}
        self._current_words = []
        self._is_processed = False
        self._normalization_cache = {}
        self._last_input_hash = None
        self._max_words = 1000
        self._min_word_length = 1
        self._default_value = 0

    def _normalize_word(self, word):
        if word in self._normalization_cache:
            return self._normalization_cache[word]
        _normalized = word.lower()
        self._normalization_cache[word] = _normalized
        return _normalized

    def _update_counts(self):
        self._word_counts = {}
        for _word in self._current_words:
            if len(_word) >= self._min_word_length:
                _normalized = self._normalize_word(_word)
                self._word_counts[_normalized] = self._word_counts.get(_normalized, self._default_value) + 1
        self._is_processed = True

    def _get_hash_from_input(self, words):
        return hash(tuple(words))

    def word_frequency(self, words):
        _input_hash = self._get_hash_from_input(words)
        if self._last_input_hash != _input_hash or not self._is_processed:
            self._current_words = words[:self._max_words]
            self._update_counts()
            self._last_input_hash = _input_hash
        return self._word_counts

def word_frequency(words):
    _analyzer = WordFrequencyAnalyzer()
    return _analyzer.word_frequency(words)

