class TemperatureConverter:
    _celsius_to_fahrenheit_factor = 1.8
    _celsius_to_fahrenheit_offset = 32.0
    _kelvin_offset = 273.15
    _unit_map = {'C': 'celsius', 'F': 'fahrenheit', 'K': 'kelvin'}
    _conversion_functions = {}

    def __init__(self):
        self._initialize_conversions()

    def _to_celsius(self, value, unit):
        if unit == 'celsius':
            return value
        elif unit == 'fahrenheit':
            return (value - self._celsius_to_fahrenheit_offset) / self._celsius_to_fahrenheit_factor
        elif unit == 'kelvin':
            return value - self._kelvin_offset
        self._raise_invalid_unit_error(unit)

    def _from_celsius(self, value, unit):
        if unit == 'celsius':
            return value
        elif unit == 'fahrenheit':
            return value * self._celsius_to_fahrenheit_factor + self._celsius_to_fahrenheit_offset
        elif unit == 'kelvin':
            return value + self._kelvin_offset
        self._raise_invalid_unit_error(unit)

    def _initialize_conversions(self):
        for from_unit_key in self._unit_map:
            for to_unit_key in self._unit_map:
                from_unit_name = self._unit_map[from_unit_key]
                to_unit_name = self._unit_map[to_unit_key]
                self._conversion_functions[(from_unit_name, to_unit_name)] = \
                    lambda val, fr=from_unit_name, to=to_unit_name: self._from_celsius(self._to_celsius(val, fr), to)

    def _raise_invalid_unit_error(self, unit):
        raise ValueError(f"Invalid unit: {unit}")

    def convert_temperature(self, value, unit_from, unit_to):
        _from_name = self._unit_map[unit_from]
        _to_name = self._unit_map[unit_to]
        _converter = self._conversion_functions.get((_from_name, _to_name))
        if not _converter:
            self._raise_invalid_unit_error(f"Cannot convert from {_from_name} to {_to_name}")
        return _converter(value)

