        self._has_upper = any(c.isupper() for c in self._password)
        if self._has_upper:
            self._score += 1

    def _check_lowercase(self):
        self._has_lower = any(c.islower() for c in self._password)
        if self._has_lower:
            self._score += 1

    def _check_digit(self):
        self._has_digit = any(c.isdigit() for c in self._password)
        if self._has_digit:
            self._score += 1

    def _evaluate_strength(self):
        if len(self._password) >= self._min_strong_length and self._score == 3:
            self._result = 'Strong'
        elif len(self._password) >= self._min_medium_length and self._score >= 2:
            self._result = 'Medium'
        else:
            self._result = 'Weak'

    def check_password_strength(self, password):
        self._password = password
        self._score = 0
        self._check_uppercase()
        self._check_lowercase()
        self._check_digit()
        self._evaluate_strength()
        return self._result

