        self._text = text
        self._pattern = pattern
        self._text_len = len(text)
        self._pattern_len = len(pattern)
        self._occurrences = []
        self._current_index = 0
        self._has_run = False

    def _reset_state(self):
        self._occurrences = []
        self._current_index = 0
        self._has_run = False

    def _check_match(self, start_index):
        if start_index + self._pattern_len > self._text_len:
            return False
        return self._text[start_index : start_index + self._pattern_len] == self._pattern

    def _find_next(self):
        while self._current_index <= self._text_len - self._pattern_len:
            if self._check_match(self._current_index):
                self._occurrences.append(self._current_index)
            self._current_index += 1
        self._has_run = True

    def _get_results(self):
        if not self._has_run:
            self._find_next()
        return self._occurrences

    def find(self):
        self._reset_state()
        self._find_next()
        return self._get_results()

def find_all_occurrences(text, pattern):
