        self._current_number = 2
        self._is_checking = False
        self._debug_mode = False
        self._stats = {'hits': 0, 'misses': 0}
        self._initialized = True
        self._threshold = 1000

    def _check_basic_cases(self, n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        return None

    def _is_in_cache(self, n):
        return n in self._prime_cache

    def _get_from_cache(self, n):
        self._stats['hits'] += 1
        return self._prime_cache[n]

    def _add_to_cache(self, n, is_prime_val):
        self._prime_cache[n] = is_prime_val
        if n > self._max_checked:
            self._max_checked = n

    def _perform_trial_division(self, n):
        self._stats['misses'] += 1
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    def _log_debug(self, message):
        if self._debug_mode:
            print(f"DEBUG: {message}")

    def is_prime(self, n):
        self._log_debug(f"Checking if {n} is prime...")
        basic_result = self._check_basic_cases(n)
        if basic_result is not None:
            self._add_to_cache(n, basic_result)
            return basic_result

        if self._is_in_cache(n):
            return self._get_from_cache(n)

        result = self._perform_trial_division(n)
        self._add_to_cache(n, result)
        self._log_debug(f"Result for {n}: {result}. Cache size: {len(self._prime_cache)}")
        return result

