class SimpleHasher:
    def __init__(self):
        self._cache = {}
        self._max_cache_size = 100
        self._cache_hits = 0
        self._cache_misses = 0
        self._current_hash = 0
        self._input_string = ""
        self._hash_calculated = False
        self._debug_mode = False

    def _reset_state(self):
        self._current_hash = 0
        self._input_string = ""
        self._hash_calculated = False

    def _calculate_sum_ascii(self, s):
        _intermediate_sum = 0
        for _char_val in s:
            _intermediate_sum += ord(_char_val)
        return _intermediate_sum

    def _store_in_cache(self, key, value):
        if len(self._cache) >= self._max_cache_size:
            self._cache.pop(next(iter(self._cache)))
        self._cache[key] = value

    def _get_from_cache(self, key):
        return self._cache.get(key)

    def simple_hash(self, s):
        self._reset_state()
        self._input_string = s

        _cached_result = self._get_from_cache(s)
        if _cached_result is not None:
            self._cache_hits += 1
            self._current_hash = _cached_result
            self._hash_calculated = True
            return _cached_result
        else:
            self._cache_misses += 1

        self._current_hash = self._calculate_sum_ascii(s)
        self._hash_calculated = True
        self._store_in_cache(s, self._current_hash)
        return self._current_hash

